import { Link } from 'react-router-dom';

const PriceComparisonChart: React.FC<{ current: number; target: number; currency: string }> = ({ current, target, currency }) => {
    const maxVal = Math.max(current, target) * 1.1; // 10% buffer
    const currentPercent = (current / maxVal) * 100;
    const targetPercent = (target / maxVal) * 100;
    const isUpside = target > current;

    return (
        <div className="w-full mt-3">
            <div className="flex justify-between text-xs text-slate-500 mb-1">
                <span>0</span>
                <span>Actual vs Target</span>
                <span>{currency}{maxVal.toFixed(0)}</span>
            </div>
            <div className="relative h-4 bg-slate-200 rounded-full w-full overflow-hidden">
                 {/* Current Price Bar */}
                <div 
                    className="absolute top-0 left-0 h-full bg-blue-500 rounded-full z-10"
                    style={{ width: `${currentPercent}%` }}
                    title={`Current: ${currency}${current}`}
                ></div>

                {/* Target Marker */}
                 <div 
                    className={`absolute top-0 bottom-0 w-1 z-20 ${isUpside ? 'bg-green-500' : 'bg-red-500'}`}
                    style={{ left: `${targetPercent}%` }}
                    title={`Target: ${currency}${target}`}
                ></div>
            </div>
             <div className="flex justify-between text-xs mt-1">
                <span className="text-blue-600 font-bold">{currency}{current}</span>
                <span className={`${isUpside ? 'text-green-600' : 'text-red-600'} font-bold`}>{currency}{target}</span>
            </div>
        </div>
    );
};

const StockForm: React.FC<{
  stock: Omit<Stock, 'id'> | Stock | null;
  onSave: (data: Omit<Stock, 'id'>) => void;
  onCancel: () => void;
}> = ({ stock, onSave, onCancel }) => {
  const [formData, setFormData] = useState({
    name: stock?.name || '',
    ticker: stock?.ticker || '',
    description: stock?.description || '',
    imageUrl: stock?.imageUrl || '',
    currentPrice: stock?.currentPrice || 0,
    targetPrice: stock?.targetPrice || 0,
    intrinsicValue: stock?.intrinsicValue || 0,
    ratios: stock?.ratios || '',
    currency: stock?.currency || '$',
    isDemo: stock?.isDemo || false,
    newsLink: stock?.newsLink || '',
    chartLink: stock?.chartLink || '',
    tradingViewLink: stock?.tradingViewLink || '',
  });
  const [isUploading, setIsUploading] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setFormData((prev) => ({ ...prev, [name]: val }));
  };

  const convertFileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = error => reject(error);
    });
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setIsUploading(true);
      const file = e.target.files[0];
      try {
        const base64String = await convertFileToBase64(file);
        setFormData(prev => ({ ...prev, imageUrl: base64String }));
      } catch (error) {
        console.error("Error converting file to base64", error);
        alert("There was an error uploading the image. Please try again.");
      } finally {
        setIsUploading(false);
      }
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.ticker || !formData.description || !formData.imageUrl) {
        alert('Please fill out all required fields.');
        return;
    }
    const payload = {
        ...formData,
        currentPrice: Number(formData.currentPrice),
        targetPrice: Number(formData.targetPrice),
        intrinsicValue: Number(formData.intrinsicValue),
    }
    onSave(payload);
  };

  const priceLeft = Math.max(0, Number(formData.targetPrice) - Number(formData.currentPrice));
  const upside = formData.currentPrice > 0 ? (priceLeft / Number(formData.currentPrice)) * 100 : 0;

  return (
    <form onSubmit={handleSubmit} className="space-y-4 max-h-[75vh] overflow-y-auto px-1">
      <div className="grid grid-cols-2 gap-4">
        <div>
            <label className="block text-sm font-medium text-slate-600 mb-1">Company Name</label>
            <input name="name" type="text" value={formData.name} onChange={handleChange} className="w-full px-3 py-2 border bg-white text-slate-900 border-slate-300 rounded-lg" required />
        </div>
        <div>
            <label className="block text-sm font-medium text-slate-600 mb-1">Ticker Symbol</label>
            <input name="ticker" type="text" value={formData.ticker} onChange={handleChange} className="w-full px-3 py-2 border bg-white text-slate-900 border-slate-300 rounded-lg uppercase" required />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 items-center">
         <div>
            <label className="block text-sm font-medium text-slate-600 mb-1">Currency</label>
            <select name="currency" value={formData.currency} onChange={handleChange} className="w-full px-3 py-2 border bg-white text-slate-900 border-slate-300 rounded-lg">
                <option value="$">USD ($)</option>
                <option value="€">EUR (€)</option>
                <option value="£">GBP (£)</option>
                <option value="₹">INR (₹)</option>
            </select>
         </div>
         <div className="flex items-center pt-4">
            <input id="isDemo" name="isDemo" type="checkbox" checked={formData.isDemo} onChange={handleChange} className="w-5 h-5 text-blue-600 border-gray-300 rounded" />
            <label htmlFor="isDemo" className="ml-2 block text-sm font-medium text-slate-700">Set as Public Demo</label>
         </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 p-4 bg-slate-50 rounded-xl border">
          <div>
            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Current Price</label>
            <input name="currentPrice" type="number" step="0.01" value={formData.currentPrice} onChange={handleChange} className="w-full px-3 py-2 border bg-white text-slate-900 border-slate-300 rounded-lg font-bold" required />
          </div>
          <div>
            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Target Price</label>
            <input name="targetPrice" type="number" step="0.01" value={formData.targetPrice} onChange={handleChange} className="w-full px-3 py-2 border bg-white text-slate-900 border-slate-300 rounded-lg font-bold" required />
          </div>
          <div>
            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Intrinsic Value</label>
            <input name="intrinsicValue" type="number" step="0.01" value={formData.intrinsicValue} onChange={handleChange} className="w-full px-3 py-2 border bg-white text-slate-900 border-slate-300 rounded-lg font-bold" />
          </div>
          <div className="flex flex-col justify-center">
            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Gap to Target</label>
            <div className="px-3 py-2 bg-white border border-slate-300 rounded-lg font-bold text-green-600">
                {formData.currency}{priceLeft.toFixed(2)}
            </div>
          </div>
      </div>

      <div className="space-y-4">
          <h4 className="text-sm font-bold text-slate-800 border-b pb-1">External Resources & Links</h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-slate-600 mb-1">Latest News Link</label>
                <input name="newsLink" type="url" value={formData.newsLink} onChange={handleChange} placeholder="https://news-source.com/..." className="w-full px-3 py-2 border bg-white text-slate-900 border-slate-300 rounded-lg text-sm" />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-600 mb-1">Chart Image Link</label>
                <input name="chartLink" type="url" value={formData.chartLink} onChange={handleChange} placeholder="https://image-hosting.com/chart.png" className="w-full px-3 py-2 border bg-white text-slate-900 border-slate-300 rounded-lg text-sm" />
              </div>
              <div className="md:col-span-2">
                <label className="block text-xs font-medium text-slate-600 mb-1">TradingView Link / Embed URL</label>
                <input name="tradingViewLink" type="url" value={formData.tradingViewLink} onChange={handleChange} placeholder="https://www.tradingview.com/chart/..." className="w-full px-3 py-2 border bg-white text-slate-900 border-slate-300 rounded-lg text-sm" />
              </div>
          </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-slate-600 mb-1">Key Ratios (One per line)</label>
        <textarea name="ratios" rows={3} value={formData.ratios} onChange={handleChange} placeholder="P/E: 25.4&#10;ROE: 15%" className="w-full px-3 py-2 border bg-white text-slate-900 border-slate-300 rounded-lg text-sm" />
      </div>

      <div>
        <label className="block text-sm font-medium text-slate-600 mb-1">Analysis Summary</label>
        <textarea name="description" rows={4} value={formData.description} onChange={handleChange} className="w-full px-3 py-2 border bg-white text-slate-900 border-slate-300 rounded-lg text-sm" required />
      </div>

      <div>
        <label className="block text-sm font-medium text-slate-600 mb-1">Thumbnail Image</label>
        {formData.imageUrl && (
            <div className="mb-2"><img src={formData.imageUrl} alt="preview" className="w-full h-32 object-cover rounded-lg" /></div>
        )}
        <label className="cursor-pointer bg-slate-100 hover:bg-slate-200 text-slate-700 py-2 px-4 border border-dashed border-slate-300 rounded-lg flex items-center justify-center w-full">
            {isUploading ? <span>Uploading...</span> : <span>{formData.imageUrl ? 'Change Thumbnail' : 'Upload Thumbnail'}</span>}
            <input type="file" accept="image/*" onChange={handleImageUpload} className="hidden" disabled={isUploading} />
        </label>
      </div>
      <div className="flex justify-end space-x-3 pt-4 border-t">
        <button type="button" onClick={onCancel} className="px-4 py-2 bg-slate-200 text-slate-800 rounded-lg hover:bg-slate-300">Cancel</button>
        <button type="submit" className="px-4 py-2 bg-blue-700 text-white rounded-lg hover:bg-blue-800">Save Stock</button>
      </div>
    </form>
  );
};

const ServicesPage: React.FC = () => {
  const { stocks, addStock, updateStock, deleteStock } = useAuth();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingStock, setEditingStock] = useState<Stock | null>(null);
  const [isConfirmModalOpen, setIsConfirmModalOpen] = useState(false);
  const [stockToDelete, setStockToDelete] = useState<Stock | null>(null);

  const activeStocks = stocks.filter(s => !s.isDeleted);

  const handleAddNew = () => {
    setEditingStock(null);
    setIsModalOpen(true);
  };

  const handleEdit = (stock: Stock) => {
    setEditingStock(stock);
    setIsModalOpen(true);
  };

  const handleDeleteClick = (stock: Stock) => {
    setStockToDelete(stock);
    setIsConfirmModalOpen(true);
  };

  const confirmDelete = () => {
    if (stockToDelete) {
      deleteStock(stockToDelete.id);
      setStockToDelete(null);
      setIsConfirmModalOpen(false);
    }
  };

  const handleSave = (stockData: Omit<Stock, 'id'>) => {
    if (editingStock) {
      updateStock({ ...stockData, id: editingStock.id });
    } else {
      addStock(stockData);
    }
    setIsModalOpen(false);
  };

  return (
    <div className="space-y-6">
        <Link to="/admin/app-modify" className="inline-flex items-center gap-2 text-sm font-medium text-slate-600 hover:text-blue-700 transition-colors">
            <ArrowLeftIcon className="w-5 h-5" /> Back to App Modify
        </Link>
        <div className="bg-white p-6 rounded-xl shadow-md flex justify-between items-center">
            <div>
                <h1 className="text-xl font-bold text-slate-800">Stock Recommendations Management</h1>
                <p className="text-sm text-slate-500 mt-1">Manage core analysis, price targets, and external data for each pick.</p>
            </div>
            <button onClick={handleAddNew} className="bg-blue-700 text-white font-semibold px-5 py-2 rounded-lg hover:bg-blue-800 transition-colors">
            + Add New Stock
            </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {activeStocks.map((stock) => (
            <div key={stock.id} className="bg-white rounded-xl shadow-md overflow-hidden flex flex-col transition-shadow hover:shadow-lg relative">
                 {stock.isDemo && (
                    <div className="absolute top-2 left-2 bg-yellow-400 text-yellow-900 text-xs font-bold px-2 py-1 rounded z-10">DEMO PICK</div>
                )}
                <img src={stock.imageUrl} alt={stock.name} className="w-full aspect-video object-cover" />
                <div className="p-6 flex-grow flex flex-col">
                    <div className="flex justify-between items-start mb-2">
                        <div>
                            <h3 className="text-xl font-semibold text-slate-800">{stock.name}</h3>
                            <span className="text-xs font-bold text-slate-500 bg-slate-100 px-2 py-0.5 rounded uppercase">{stock.ticker}</span>
                        </div>
                        <div className="text-right">
                            <div className="text-lg font-bold text-slate-800">{stock.currency}{stock.currentPrice}</div>
                        </div>
                    </div>

                    <PriceComparisonChart current={stock.currentPrice} target={stock.targetPrice} currency={stock.currency} />

                    <div className="grid grid-cols-2 gap-2 mt-4 text-xs">
                        <div className="p-2 bg-slate-50 rounded">
                            <span className="text-slate-400 block uppercase">Target Gap</span>
                            <span className="font-bold text-green-600">{stock.currency}{(stock.targetPrice - stock.currentPrice).toFixed(2)}</span>
                        </div>
                        <div className="p-2 bg-slate-50 rounded">
                            <span className="text-slate-400 block uppercase">Intrinsic</span>
                            <span className="font-bold text-purple-600">{stock.currency}{stock.intrinsicValue}</span>
                        </div>
                    </div>
                </div>
                <div className="p-4 bg-slate-50 border-t flex justify-end items-center space-x-4">
                <button onClick={() => handleEdit(stock)} className="text-sm font-medium text-blue-600 hover:text-blue-800">Edit Analysis</button>
                <button onClick={() => handleDeleteClick(stock)} className="text-slate-400 hover:text-red-600"><TrashIcon className="w-5 h-5" /></button>
                </div>
            </div>
            ))}
        </div>

        {isModalOpen && (
            <Modal title={editingStock ? 'Edit Stock Analysis' : 'Add New Stock Recommendation'} onClose={() => setIsModalOpen(false)}>
                <StockForm stock={editingStock} onSave={handleSave} onCancel={() => setIsModalOpen(false)} />
            </Modal>
        )}

        {isConfirmModalOpen && stockToDelete && (
            <Modal title="Confirm Deletion" onClose={() => setIsConfirmModalOpen(false)}>
                <div className="text-center">
                    <p className="text-slate-600 text-lg">Move <span className="font-bold">"{stockToDelete.name}"</span> to trash?</p>
                    <div className="flex justify-center space-x-4 mt-8">
                        <button onClick={() => setIsConfirmModalOpen(false)} className="px-6 py-2 bg-slate-200 text-slate-800 rounded-lg hover:bg-slate-300">Cancel</button>
                        <button onClick={confirmDelete} className="px-6 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700">Delete</button>
                    </div>
                </div>
            </Modal>
        )}
    </div>
  );
};

export default ServicesPage;

